+KIO::WorkerResult KioBluetooth::copy(const QUrl &src, const QUrl &dest, int permissions, KIO::JobFlags flags)
+{
+    Q_UNUSED(permissions)
+    Q_UNUSED(flags)
+
+    qCDebug(BLUETOOTH) << "Copy: " << src << dest;
+
+    if (!src.isLocalFile() || !isSendFileUrl(dest.adjusted(QUrl::RemoveFilename))) {
+        return KIO::WorkerResult::fail(KIO::ERR_UNSUPPORTED_ACTION, dest.toDisplayString());
+    }
+
+    if (QFileInfo(src.toLocalFile()).isDir()) {
+        return KIO::WorkerResult::fail(KIO::ERR_IS_DIRECTORY, src.toLocalFile());
+    }
+
+    m_kded->stopDiscovering();
+    infoMessage(i18n("Connecting to the device"));
+
+    BluezQt::ObexManager manager;
+    BluezQt::InitObexManagerJob *initJob = manager.init();
+    initJob->exec();
+    if (initJob->error() || !manager.isOperational()) {
+        return KIO::WorkerResult::fail(KIO::ERR_WORKER_DEFINED, i18n("Obexd service is not running."));
+    }
+
+    QVariantMap args;
+    args[QStringLiteral("Target")] = QStringLiteral("opp");
+    BluezQt::PendingCall *call = manager.createSession(m_currentHostAddress, args);
+    call->waitForFinished();
+    if (call->error()) {
+        qCWarning(BLUETOOTH) << "Error creating session" << call->errorText();
+        return KIO::WorkerResult::fail(KIO::ERR_CANNOT_CONNECT, m_currentHostAddress);
+    }
+
+    const QDBusObjectPath session = call->value().value<QDBusObjectPath>();
+    const KIO::WorkerResult result = sendFile(session, src.toLocalFile());
+    manager.removeSession(session)->waitForFinished();
+    infoMessage(QString());
+    return result;
+}
+
+KIO::WorkerResult KioBluetooth::sendFile(const QDBusObjectPath &session, const QString &fileName)
+{
+    BluezQt::ObexObjectPush objectPush(session);
+    BluezQt::PendingCall *call = objectPush.sendFile(fileName);
+    call->waitForFinished();
+    if (call->error()) {
+        qCWarning(BLUETOOTH) << "Error sending file" << call->errorText();
+        return KIO::WorkerResult::fail(KIO::ERR_CANNOT_WRITE, fileName);
+    }
+
+    const BluezQt::ObexTransferPtr transfer = call->value().value<BluezQt::ObexTransferPtr>();
+    totalSize(QFileInfo(fileName).size());
+
+    QEventLoop loop;
+    connect(transfer.data(), &BluezQt::ObexTransfer::transferredChanged, &loop, [this, transfer](quint64 transferred) {
+        processedSize(transferred);
+        if (wasKilled()) {
+            transfer->cancel();
+        }
+    });
+    connect(transfer.data(), &BluezQt::ObexTransfer::statusChanged, &loop, [&loop](BluezQt::ObexTransfer::Status status) {
+        if (status == BluezQt::ObexTransfer::Complete || status == BluezQt::ObexTransfer::Error) {
+            loop.quit();
+        }
+    });
+    if (transfer->status() != BluezQt::ObexTransfer::Complete && transfer->status() != BluezQt::ObexTransfer::Error) {
+        loop.exec();
+    }
+
+    if (transfer->status() != BluezQt::ObexTransfer::Complete) {
+        return KIO::WorkerResult::fail(KIO::ERR_WORKER_DEFINED, i18n("Bluetooth transfer failed"));
+    }
+    return KIO::WorkerResult::pass();
+}
+
+bool KioBluetooth::isSendFileUrl(const QUrl &url) const
+{
+    return m_hasCurrentHost && url.adjusted(QUrl::StripTrailingSlash).path() == QLatin1Char('/') + BluezQt::Services::ObexObjectPush;
+}
+
+KIO::UDSEntry KioBluetooth::sendFileFolderEntry(const QString &name) const
+{
+    const Service service = m_supportedServices.value(BluezQt::Services::ObexObjectPush);
+
+    KIO::UDSEntry entry;
+    entry.fastInsert(KIO::UDSEntry::UDS_NAME, name);
+    entry.fastInsert(KIO::UDSEntry::UDS_DISPLAY_NAME, service.name);
+    entry.fastInsert(KIO::UDSEntry::UDS_ICON_NAME, service.icon);
+    entry.fastInsert(KIO::UDSEntry::UDS_FILE_TYPE, S_IFDIR);
+    entry.fastInsert(KIO::UDSEntry::UDS_ACCESS, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
+    entry.fastInsert(KIO::UDSEntry::UDS_MIME_TYPE, QStringLiteral("inode/vnd.kde.bluedevil.service"));
+    return entry;
+}
